test({ sr: 'sabira parne brojeve', en: 'sums the even numbers' }, () => {
  expect(sumEvens([1, 2, 3, 4])).toBe(6);
});
test({ sr: 'vraća 0 kad nema parnih', en: 'returns 0 when there are no even numbers' }, () => {
  expect(sumEvens([1, 3, 5])).toBe(0);
});
test({ sr: 'prazan niz daje 0', en: 'an empty array gives 0' }, () => {
  expect(sumEvens([])).toBe(0);
});

